import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import Layout from '../components/Layout';
import apiClient from '../config/axios';
import config from '../config/config';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import TransactionLoader from '../components/TransactionLoader';
import './AddItem.css';

const AddItem = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const toast = useToast();
  const itemSearchInputRef = useRef(null);
  const [buyerParties, setBuyerParties] = useState([]);
  const [selectedBuyer, setSelectedBuyer] = useState('');
  const [buyerInfo, setBuyerInfo] = useState(null);
  const [buyerSearchQuery, setBuyerSearchQuery] = useState('');
  const [filteredBuyerParties, setFilteredBuyerParties] = useState([]);
  const [showBuyerSuggestions, setShowBuyerSuggestions] = useState(false);
  const [loadingBuyerParties, setLoadingBuyerParties] = useState(true);
  const [buyerPartiesError, setBuyerPartiesError] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState('');
  const [suggestedItems, setSuggestedItems] = useState([]);
  const [selectedItems, setSelectedItems] = useState([]);
  const [selectedItemIds, setSelectedItemIds] = useState(new Set()); // For multi-select
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [purchasePaymentStatus, setPurchasePaymentStatus] = useState('partially_paid');
  const [purchasePaidAmount, setPurchasePaidAmount] = useState(0);

  // New Item Form State
  const [showAddItemForm, setShowAddItemForm] = useState(false);
  const [isAddingNewItem, setIsAddingNewItem] = useState(false);
  const [newItem, setNewItem] = useState({
    product_name: '',
    product_code: '',
    brand: '',
    hsn_number: '',
    tax_rate: 18,
    sale_rate: 0,
    purchase_rate: 0,
    quantity: 0,
    alert_quantity: 0,
    rack_number: '',
    remarks: ''
  });
  const [itemImage, setItemImage] = useState(null);

  const purchaseTotal = selectedItems.reduce((sum, it) => {
    const qty = parseInt(it.quantity) || 0;
    const rate = parseFloat(it.purchase_rate) || 0;
    return sum + qty * rate;
  }, 0);
  // Round purchase total to whole number
  const roundedPurchaseTotal = Math.round(purchaseTotal);
  // Round paid amount to whole number (no decimals)
  const purchasePaidNow = purchasePaymentStatus === 'fully_paid' ? roundedPurchaseTotal : Math.max(0, Math.round(purchasePaidAmount || 0));
  // Calculate balance using rounded values
  const purchaseBalance = Math.max(0, roundedPurchaseTotal - purchasePaidNow);

  useEffect(() => {
    // Check if user has permission to add items
    if (user) {
      if (user.role !== 'admin' && user.role !== 'super_admin') {
        alert('Access Denied: Only Admin and Super Admin can add items to inventory.');
        navigate('/dashboard');
        return;
      }
      fetchBuyerParties();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user, navigate]);

  useEffect(() => {
    if (selectedBuyer) {
      fetchBuyerInfo();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedBuyer]);

  useEffect(() => {
    if (buyerSearchQuery.trim() === '') {
      setFilteredBuyerParties(buyerParties);
      setShowBuyerSuggestions(false);
    } else {
      const trimmedQuery = buyerSearchQuery.trim().toLowerCase();
      const filtered = buyerParties.filter(party =>
        (party.party_name || '').toLowerCase().includes(trimmedQuery) ||
        (party.mobile_number && party.mobile_number.includes(buyerSearchQuery.trim())) ||
        (party.address && (party.address || '').toLowerCase().includes(trimmedQuery))
      );
      setFilteredBuyerParties(filtered);
      setShowBuyerSuggestions(true);
    }
  }, [buyerSearchQuery, buyerParties]);

  const [isLoadingItems, setIsLoadingItems] = useState(false);

  // Debounce search query - update debouncedSearchQuery after 1 second of no typing
  useEffect(() => {
    const timer = setTimeout(() => {
      const trimmedQuery = searchQuery.trim();
      setDebouncedSearchQuery(trimmedQuery);
    }, 1000); // 1 second delay

    return () => clearTimeout(timer);
  }, [searchQuery]);

  useEffect(() => {
    const trimmedQuery = debouncedSearchQuery.trim();
    if (trimmedQuery.length >= 2) {
      searchItems();
    } else {
      setSuggestedItems([]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [debouncedSearchQuery]);

  const fetchBuyerParties = async () => {
    setLoadingBuyerParties(true);
    setBuyerPartiesError(null);
    try {
      const response = await apiClient.get(config.api.buyers);
      setBuyerParties(response.data.parties || []);
    } catch (error) {
      console.error('Error fetching buyer parties:', error);
      setBuyerPartiesError(error.response?.data?.error || 'Server error. Please try again.');
      toast.error('Error fetching buyer parties: ' + (error.response?.data?.error || 'Server error'));
    } finally {
      setLoadingBuyerParties(false);
    }
  };

  const fetchBuyerInfo = async () => {
    try {
      const response = await apiClient.get(`${config.api.buyers}/${selectedBuyer}`);
      setBuyerInfo(response.data.party);
      setBuyerSearchQuery(response.data.party.party_name);
      setShowBuyerSuggestions(false);
    } catch (error) {
      console.error('Error fetching buyer info:', error);
    }
  };

  const selectBuyerParty = (party) => {
    setSelectedBuyer(party.id);
    setBuyerSearchQuery(party.party_name);
    setShowBuyerSuggestions(false);
  };

  const searchItems = async () => {
    setIsLoadingItems(true);
    try {
      const trimmedQuery = debouncedSearchQuery.trim();
      const response = await apiClient.get(config.api.itemsSearch, {
        params: { 
          q: trimmedQuery,
          include_purchase_rate: 'true' // AddItem is for buyer purchase, needs purchase_rate
        }
      });
      setSuggestedItems(response.data.items);
    } catch (error) {
      console.error('Error searching items:', error);
    } finally {
      setIsLoadingItems(false);
    }
  };

  // eslint-disable-next-line no-unused-vars
  const handleToggleItemSelection = (itemId) => {
    setSelectedItemIds(prev => {
      const newSet = new Set(prev);
      if (newSet.has(itemId)) {
        newSet.delete(itemId);
      } else {
        newSet.add(itemId);
      }
      return newSet;
    });
  };

  // eslint-disable-next-line no-unused-vars
  const handleAddSelectedItems = async () => {
    if (selectedItemIds.size === 0) {
      toast.warning('Please select at least one item');
      return;
    }

    const itemsToAdd = suggestedItems.filter(item => selectedItemIds.has(item.id));
    let successCount = 0;
    let errorCount = 0;
    
    try {
      // Fetch all item details in a single batch API call
      const itemIds = itemsToAdd.map(item => item.id);
      const response = await apiClient.post(config.api.itemsDetails, {
        item_ids: itemIds,
        include_purchase_rate: true // AddItem is for buyer purchase, needs purchase_rate
      });

      // Create a map of item_id -> item details for quick lookup
      const itemsDetailsMap = new Map();
      if (response.data && response.data.items) {
        response.data.items.forEach(item => {
          itemsDetailsMap.set(item.id, item);
        });
      }

      // Add items to cart using batch API data
      setSelectedItems(prev => {
        const updatedItems = [...prev];
        itemsToAdd.forEach(item => {
          const itemDetails = itemsDetailsMap.get(item.id);
          if (!itemDetails) {
            errorCount++;
            return;
          }

          // Parse tax_rate
          const taxRateValue = itemDetails.tax_rate !== undefined && itemDetails.tax_rate !== null
            ? parseFloat(itemDetails.tax_rate)
            : 18;
          const validTaxRates = [5, 18, 28];
          const finalTaxRate = !isNaN(taxRateValue) && validTaxRates.includes(taxRateValue) 
            ? taxRateValue 
            : 18;

          const existingItemIndex = updatedItems.findIndex(i => i.item_id === item.id);
          if (existingItemIndex >= 0) {
            // If item already in cart, just increment quantity
            updatedItems[existingItemIndex] = {
              ...updatedItems[existingItemIndex],
              quantity: updatedItems[existingItemIndex].quantity + 1
            };
          } else {
            // Add new item to cart - use search data which now includes purchase_rate
            // Note: current_quantity should be the actual stock from the database
            // The quantity field is the purchase quantity (how many we're buying)
            updatedItems.push({
              item_id: itemDetails.id,
              product_name: itemDetails.product_name,
              product_code: itemDetails.product_code || '',
              brand: itemDetails.brand || '',
              hsn_number: itemDetails.hsn_number || '',
              tax_rate: finalTaxRate,
              sale_rate: parseFloat(itemDetails.sale_rate) || 0,
              purchase_rate: parseFloat(itemDetails.purchase_rate) || 0,
              quantity: 1, // Purchase quantity (how many we're buying) - starts at 1
              alert_quantity: 0, // Will be set when submitting
              rack_number: '', // Will be set when submitting
              remarks: '', // Will be set when submitting
              current_quantity: parseInt(itemDetails.quantity) || 0 // Actual stock from database
            });
          }
          successCount++;
        });
        return updatedItems;
      });
    } catch (error) {
      console.error('Error fetching batch item details:', error);
      toast.error('Error loading item details');
      errorCount += itemsToAdd.length;
    }
    
    if (successCount > 0) {
      toast.success(`✓ Added ${successCount} item${successCount !== 1 ? 's' : ''} to purchase list`);
    }
    if (errorCount > 0) {
      toast.error(`Failed to add ${errorCount} item${errorCount !== 1 ? 's' : ''}`);
    }
    
    setSelectedItemIds(new Set());
    setSearchQuery('');
    setSuggestedItems([]);
  };

  const addItemToCart = async (item) => {
    try {
      // Note: We allow adding items even if out of stock, since this is for filling inventory
      // Use search data directly (which now includes purchase_rate) instead of making another API call
      // The search API already returns all necessary fields including purchase_rate
      
      // Parse tax_rate to ensure it's a number (backend might send it as string)
      const taxRateValue = item.tax_rate !== undefined && item.tax_rate !== null
        ? parseFloat(item.tax_rate)
        : 18;
      const validTaxRates = [5, 18, 28];
      const finalTaxRate = !isNaN(taxRateValue) && validTaxRates.includes(taxRateValue) 
        ? taxRateValue 
        : 18;
      
      const existingItem = selectedItems.find(i => i.item_id === item.id);
      if (existingItem) {
        // If item already in cart, just increment quantity
        setSelectedItems(prev => prev.map(i =>
          i.item_id === item.id ? { ...i, quantity: i.quantity + 1 } : i
        ));
      } else {
        // Add item using search data (which includes purchase_rate)
        // Note: current_quantity should be the actual stock from the database
        // The quantity field is the purchase quantity (how many we're buying)
        setSelectedItems(prev => [...prev, {
          item_id: item.id,
          product_name: item.product_name,
          product_code: item.product_code || '',
          brand: item.brand || '',
          hsn_number: item.hsn_number || '',
          tax_rate: finalTaxRate, // Use the parsed and validated tax rate
          sale_rate: parseFloat(item.sale_rate) || 0,
          purchase_rate: parseFloat(item.purchase_rate) || 0,
          quantity: 1, // Purchase quantity (how many we're buying) - starts at 1
          alert_quantity: 0, // Will be set when submitting
          rack_number: '', // Will be set when submitting
          remarks: '', // Will be set when submitting
          current_quantity: parseInt(item.quantity) || 0 // Actual stock from database (for reference only)
        }]);
      }
      
      // Don't clear search or close modal - allow adding multiple items
      // Keep UX smooth: no toast spam on every item add
    } catch (error) {
      console.error('Error fetching item details:', error);
      toast.error('Error loading item details');
    }
  };

  const handleSearchClear = () => {
    setSearchQuery('');
    setSuggestedItems([]);
    setActiveSuggestionIndex(-1);
  };

  // Close suggestions when clicking outside or pressing Escape
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (!event.target.closest('.table-search-wrapper')) {
        setSuggestedItems([]);
      }
    };

    const handleEscapeKey = (event) => {
      if (event.key === 'Escape') {
        handleSearchClear();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscapeKey);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, []);

  const updateItem = (itemId, field, value) => {
    setSelectedItems(selectedItems.map(item =>
      item.item_id === itemId ? { ...item, [field]: value } : item
    ));
  };

  const removeItem = (itemId) => {
    setSelectedItems(selectedItems.filter(item => item.item_id !== itemId));
  };

  const closeAddItemModal = () => {
    setShowAddItemForm(false);
    setNewItem({
      product_name: '',
      product_code: '',
      brand: '',
      hsn_number: '',
      tax_rate: 18,
      sale_rate: 0,
      purchase_rate: 0,
      quantity: 0,
      alert_quantity: 0,
      rack_number: '',
      remarks: ''
    });
    setItemImage(null);
  };

  const handleAddNewItem = async () => {
    // Validate required fields
    if (!newItem.product_name) {
      toast.warning('Product name is required');
      return;
    }
    const qty = Number(newItem.quantity);
    if (qty < 0 || isNaN(qty)) {
      toast.warning('Valid quantity is required (use 0 or more)');
      return;
    }
    if (!newItem.purchase_rate || newItem.purchase_rate < 0) {
      toast.warning('Purchase rate is required');
      return;
    }
    if (newItem.sale_rate && parseFloat(newItem.sale_rate) < parseFloat(newItem.purchase_rate)) {
      if (!window.confirm('Sale rate is lower than purchase rate. Continue?')) {
        return;
      }
    }

    setIsAddingNewItem(true);
    try {
      const formData = new FormData();
      formData.append('product_name', newItem.product_name);
      if (newItem.product_code) formData.append('product_code', newItem.product_code);
      if (newItem.brand) formData.append('brand', newItem.brand);
      if (newItem.hsn_number) formData.append('hsn_number', newItem.hsn_number);
      formData.append('tax_rate', newItem.tax_rate);
      formData.append('purchase_rate', newItem.purchase_rate);
      formData.append('sale_rate', newItem.sale_rate);
      formData.append('quantity', newItem.quantity);
      if (newItem.alert_quantity) formData.append('alert_quantity', newItem.alert_quantity);
      if (newItem.rack_number) formData.append('rack_number', newItem.rack_number);
      if (newItem.remarks) formData.append('remarks', newItem.remarks);
      
      if (itemImage) {
        formData.append('image', itemImage);
      }

      const response = await apiClient.post(config.api.items, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      const items = selectedItems;
      const createdItem = response.data.item;
            
      // Add to selectedItems list directly
      const itemToAdd = {
        item_id: createdItem.id,
        product_name: createdItem.product_name,
        product_code: createdItem.product_code || '',
        brand: createdItem.brand || '',
        hsn_number: createdItem.hsn_number || '',
        tax_rate: parseFloat(createdItem.tax_rate) || 0,
        sale_rate: parseFloat(createdItem.sale_rate) || 0,
        purchase_rate: parseFloat(createdItem.purchase_rate) || 0,
        quantity: parseInt(newItem.quantity) || 0, // The quantity added in purchase
        current_quantity: parseInt(createdItem.quantity) || parseInt(newItem.quantity) 
      };
      
      setSelectedItems([...items, itemToAdd]);
      
      toast.success(`Product "${newItem.product_name}" created and added to list.`);
      closeAddItemModal();
      
    } catch (error) {
      console.error(error);
      const errorMessage = error.response?.data?.error || error.message || 'Unknown error occurred';
      toast.error('Error adding item: ' + errorMessage);
    } finally {
      setIsAddingNewItem(false);
    }
  };


  const handleSubmit = async () => {
    if (isSubmitting) return;
    
    if (!selectedBuyer) {
      alert('Please select a buyer party');
      return;
    }
    if (selectedItems.length === 0) {
      alert('Please add at least one item');
      return;
    }

    setIsSubmitting(true);
    try {
      await apiClient.post(config.api.itemsPurchase, {
        buyer_party_id: selectedBuyer,
        items: selectedItems,
        payment_status: purchasePaymentStatus,
        paid_amount: purchasePaidNow // Already rounded to whole number
      });
      toast.success('Items added successfully!');
      setSelectedItems([]);
      setSelectedBuyer('');
      setBuyerInfo(null);
      setPurchasePaymentStatus('partially_paid');
      setPurchasePaidAmount(0);
    } catch (error) {
      const errorMessage = error.response?.data?.error || 'Unknown error occurred';
      toast.error('Error saving items: ' + errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  // Show access denied message if sales user somehow reaches here
  if (user && user.role !== 'admin' && user.role !== 'super_admin') {
    return (
      <Layout>
        <div className="add-item">
          <div style={{ padding: '20px', textAlign: 'center', color: '#ff6b6b' }}>
            <h2>Access Denied</h2>
            <p>Only Admin and Super Admin can add items to inventory.</p>
            <Link to="/dashboard" className="btn btn-primary" style={{ marginTop: '20px' }}>
              Go to Dashboard
            </Link>
          </div>
        </div>
      </Layout>
    );
  }


  return (
    <Layout>
      <TransactionLoader isLoading={isSubmitting} type="purchase" />
      <div className="add-item">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '16px', marginBottom: '20px' }}>
          <div>
            <h2 style={{ margin: 0 }}>Add Item to Inventory</h2>
            <p style={{ color: '#666', marginTop: '8px', marginBottom: 0 }}>
              First select a buyer party, then search or add items. Submit when ready to record the purchase.
            </p>
          </div>
          <button
            type="button"
            onClick={() => setShowAddItemForm(true)}
            className="btn btn-primary"
            style={{
              padding: '10px 20px',
              fontSize: '15px',
              fontWeight: '600',
              borderRadius: '8px',
              border: 'none',
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              color: 'white',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              flexShrink: 0
            }}
          >
            <span>+</span>
            Add New Item
          </button>
        </div>

        <div className="card">
          {/* 1. Select Buyer Party first */}
          <div className="form-group">
            <label>Select Buyer Party *</label>
            <div className="search-wrapper" style={{ position: 'relative' }}>
              <input
                type="text"
                placeholder="Search buyer party by name, mobile, or address..."
                value={buyerSearchQuery}
                onChange={(e) => {
                  setBuyerSearchQuery(e.target.value);
                  if (!e.target.value) {
                    setSelectedBuyer('');
                    setBuyerInfo(null);
                  }
                }}
                onFocus={() => {
                  if (buyerSearchQuery) {
                    setShowBuyerSuggestions(true);
                  }
                }}
              />
              {showBuyerSuggestions && filteredBuyerParties.length > 0 && (
                <div className="suggestions" style={{ position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 1000, maxHeight: '200px', overflowY: 'auto' }}>
                  {filteredBuyerParties.map(party => (
                    <div
                      key={party.id}
                      className="suggestion-item"
                      onClick={() => selectBuyerParty(party)}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: '10px'
                      }}
                    >
                      <span style={{ fontWeight: '600' }}>{party.party_name}</span>
                      {party.mobile_number && (
                        <span style={{ fontSize: '12px', color: '#6c757d', whiteSpace: 'nowrap' }}>
                          📱 {party.mobile_number}
                        </span>
                      )}
                    </div>
                  ))}
                </div>
              )}
              {buyerSearchQuery && filteredBuyerParties.length === 0 && (
                <div className="suggestions" style={{ position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 1000 }}>
                  <div className="suggestion-item">No buyer party found</div>
                </div>
              )}
            </div>
            {loadingBuyerParties ? (
              <p style={{ color: '#666', fontSize: '14px', marginTop: '5px' }}>
                Fetching buyer parties...
              </p>
            ) : buyerPartiesError ? (
              <p style={{ color: '#ff6b6b', fontSize: '14px', marginTop: '5px' }}>
                {buyerPartiesError}
              </p>
            ) : buyerParties.length === 0 ? (
              <p style={{ color: '#ff6b6b', fontSize: '14px', marginTop: '5px' }}>
                No buyer parties found. Please <Link to="/add-buyer-party">add a buyer party</Link> first.
              </p>
            ) : null}
          </div>

          {buyerInfo && (
            <div className="buyer-info" style={{ 
              display: 'grid', 
              gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', 
              gap: '15px',
              marginTop: '15px',
              padding: '15px',
              backgroundColor: '#f9f9f9',
              borderRadius: '5px'
            }}>
              <div><strong>Name:</strong> {buyerInfo.party_name}</div>
              <div><strong>Mobile:</strong> {buyerInfo.mobile_number || 'N/A'}</div>
              <div><strong>Address:</strong> {buyerInfo.address || 'N/A'}</div>
              {buyerInfo.gst_number && <div><strong>GST Number:</strong> {buyerInfo.gst_number}</div>}
              <div><strong>Balance Amount:</strong> ₹{buyerInfo.balance_amount || 0}</div>
              <div><strong>Paid Amount:</strong> ₹{buyerInfo.paid_amount || 0}</div>
            </div>
          )}

          {/* Search instructions or other secondary actions could go here if needed, but the main search is now inline */}
          <div style={{ marginTop: '20px', color: '#666', fontSize: '14px' }}>
            <p>Select a buyer party above, then add items to the purchase list using the search row in the table below.</p>
          </div>


          {selectedBuyer && (
            <div className="selected-items" style={{ marginTop: '30px' }}>
              <div style={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                marginBottom: '20px'
              }}>
                <h3 style={{ margin: 0 }}>Purchase List ({selectedItems.length})</h3>
                <div style={{ display: 'flex', gap: '10px' }}>
                  {selectedItems.length > 0 && (
                    <button
                      onClick={() => {
                        if (window.confirm('Clear all items from purchase list?')) {
                          setSelectedItems([]);
                          toast.info('List cleared');
                        }
                      }}
                      className="btn btn-danger"
                      style={{ padding: '8px 16px', fontSize: '13px' }}
                    >
                      🗑️ Clear All
                    </button>
                  )}
                </div>
              </div>
              
              <div className="table-responsive-container">
                <table className="table">
                  <thead style={{ backgroundColor: '#34495e', color: '#ffffff' }}>
                    <tr>
                      <th style={{ textAlign: 'left', padding: '14px 18px' }}>Product Details</th>
                      <th style={{ textAlign: 'left', padding: '14px 18px' }}>Brand</th>
                      <th style={{ textAlign: 'right', padding: '14px 18px' }}>Purchase Rate</th>
                      <th style={{ textAlign: 'right', padding: '14px 18px' }}>Tax Rate</th>
                      <th style={{ textAlign: 'right', padding: '14px 18px', width: '100px' }}>Quantity</th>
                      <th style={{ textAlign: 'right', padding: '14px 18px' }}>Total</th>
                      <th style={{ textAlign: 'center', padding: '14px 18px' }}>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {selectedItems.map((item, index) => (
                      <tr key={index}>
                        <td style={{ textAlign: 'left' }}>
                          <div style={{ fontWeight: '700', fontSize: '15px' }}>{item.product_name}</div>
                          <div style={{ fontSize: '12px', color: '#666', marginTop: '2px' }}>
                            {item.product_code || 'No Code'} • {item.hsn_number ? `HSN: ${item.hsn_number}` : 'No HSN'}
                          </div>
                        </td>
                        <td style={{ textAlign: 'left' }}>{item.brand || '-'}</td>
                        <td style={{ textAlign: 'right', fontWeight: '600' }}>₹{parseFloat(item.purchase_rate || 0).toFixed(2)}</td>
                        <td style={{ textAlign: 'right' }}>{item.tax_rate || 0}%</td>
                        <td style={{ textAlign: 'right' }}>
                          <input
                            type="number"
                            min="1"
                            value={item.quantity === 0 ? '' : item.quantity}
                            onChange={(e) => {
                              const val = e.target.value;
                              const qty = val === '' ? 0 : parseInt(val) || 0;
                              updateItem(item.item_id, 'quantity', qty);
                            }}
                            className="table-search-input"
                            style={{ width: '80px', textAlign: 'center', padding: '6px' }}
                          />
                        </td>
                        <td style={{ textAlign: 'right', fontWeight: 'bold', color: '#2c3e50' }}>
                          ₹{(parseFloat(item.purchase_rate || 0) * (parseInt(item.quantity) || 0)).toFixed(2)}
                        </td>
                        <td style={{ textAlign: 'center' }}>
                          <button
                            onClick={() => removeItem(item.item_id)}
                            style={{ 
                              background: '#fff5f5', 
                              border: '1px solid #feb2b2', 
                              color: '#e53e3e', 
                              cursor: 'pointer', 
                              padding: '6px 10px',
                              borderRadius: '6px',
                              transition: 'all 0.2s'
                            }}
                            onMouseEnter={(e) => e.target.style.background = '#fed7d7'}
                            onMouseLeave={(e) => e.target.style.background = '#fff5f5'}
                            title="Remove"
                          >
                            🗑️
                          </button>
                        </td>
                      </tr>
                    ))}
                    
                    {/* Inline Search Row */}
                    <tr className="table-search-row">
                      <td colSpan="3" style={{ position: 'relative', overflow: 'visible', zIndex: 10005 }}>
                        <div className="table-search-wrapper">
                          <input
                            type="text"
                            className="table-search-input"
                            placeholder="🔍 Type product name, brand, or HSN to add existing item..."
                            value={searchQuery}
                            ref={itemSearchInputRef}
                            onChange={(e) => {
                              setSearchQuery(e.target.value);
                              setActiveSuggestionIndex(-1);
                            }}
                            onKeyDown={(e) => {
                              if (e.key === 'ArrowDown') {
                                e.preventDefault();
                                setActiveSuggestionIndex(prev => Math.min(prev + 1, suggestedItems.length - 1));
                              } else if (e.key === 'ArrowUp') {
                                e.preventDefault();
                                setActiveSuggestionIndex(prev => Math.max(prev - 1, -1));
                              } else if (e.key === 'Enter') {
                                e.preventDefault();
                                if (activeSuggestionIndex >= 0 && suggestedItems[activeSuggestionIndex]) {
                                  addItemToCart(suggestedItems[activeSuggestionIndex]);
                                  handleSearchClear();
                                } else if (suggestedItems.length > 0) {
                                  addItemToCart(suggestedItems[0]);
                                  handleSearchClear();
                                }
                              } else if (e.key === 'Escape') {
                                handleSearchClear();
                              }
                            }}
                          />
                          {searchQuery.trim().length >= 2 && (
                            <div className="table-suggestions">
                              <div className="table-suggestions-header">
                                <span>Product Suggestions</span>
                                {isLoadingItems && <div className="search-spinner" style={{ width: '14px', height: '14px', borderWidth: '2px' }}></div>}
                              </div>
                              <div className="table-suggestions-body">
                                {isLoadingItems && suggestedItems.length === 0 && (
                                  <div className="search-loader-container">
                                    <div className="search-spinner"></div>
                                    <span>Searching inventory...</span>
                                  </div>
                                )}
                                {!isLoadingItems && suggestedItems.length === 0 && (
                                  <div className="no-results-container">
                                    <div className="no-results-icon">🔍</div>
                                    <div>No products found for "{searchQuery}"</div>
                                  </div>
                                )}
                                {suggestedItems.map((item, idx) => {
                                  const isAlreadyInCart = selectedItems.some(it => it.item_id === item.id);
                                  const stockLevel = item.quantity || 0;
                                  const stockClass = stockLevel <= 0 ? 'none' : (stockLevel < 10 ? 'low' : 'good');
                                  const stockIcon = stockLevel <= 0 ? '🚫' : (stockLevel < 10 ? '⚠️' : '📦');

                                  return (
                                    <div
                                      key={item.id}
                                      className={`table-suggestion-item ${idx === activeSuggestionIndex ? 'active' : ''} ${isAlreadyInCart ? 'already-selected' : ''}`}
                                      onClick={() => {
                                        addItemToCart(item);
                                        handleSearchClear();
                                        itemSearchInputRef.current?.focus();
                                      }}
                                    >
                                      <div className="table-suggestion-info">
                                        <div className="table-suggestion-name">
                                          {item.product_name} 
                                          {isAlreadyInCart && <span className="selected-badge">In Cart</span>}
                                        </div>
                                        <div className="table-suggestion-meta">
                                          <span>🏢 {item.brand}</span>
                                          <span className={`stock-pill ${stockClass}`}>
                                            {stockIcon} {stockLevel} Stock
                                          </span>
                                          {item.hsn_number && <span>HSN: {item.hsn_number}</span>}
                                        </div>
                                      </div>
                                      <div className="table-suggestion-right">
                                        <div className="table-suggestion-rate" style={{ color: '#2c3e50', fontSize: '15px' }}>
                                          Purchase: <span style={{ color: '#27ae60', fontWeight: '800' }}>₹{parseFloat(item.purchase_rate || 0).toFixed(2)}</span>
                                        </div>
                                        <div style={{ fontSize: '11px', color: '#666' }}>Sale: ₹{parseFloat(item.sale_rate || 0).toFixed(2)}</div>
                                      </div>
                                    </div>
                                  );
                                })}
                              </div>
                              {suggestedItems.length > 0 && (
                                <div className="table-suggestions-footer">
                                  <span>{suggestedItems.length} results found</span>
                                  <span>↑↓ Navigate • Enter to Add</span>
                                </div>
                              )}
                            </div>
                          )}
                        </div>
                      </td>
                      <td colSpan="4" style={{ color: '#95a5a6', fontStyle: 'italic', fontSize: '13px', verticalAlign: 'middle' }}>
                        &nbsp;&nbsp;← Search and add existing items using the input on the left
                      </td>
                    </tr>
                  </tbody>
                  <tfoot style={{ position: 'relative', zIndex: 1 }}>
                    <tr style={{ background: '#f8faff' }}>
                      <td colSpan="5" style={{ textAlign: 'right', fontWeight: 'bold', borderTop: '2px solid #e1e8ed', padding: '16px' }}>
                        Cart Total:
                      </td>
                      <td style={{ textAlign: 'right', fontWeight: '800', fontSize: '18px', color: '#2c3e50', borderTop: '2px solid #e1e8ed', padding: '16px' }}>
                        ₹{purchaseTotal.toFixed(2)}
                      </td>
                      <td style={{ borderTop: '2px solid #e1e8ed' }}></td>
                    </tr>
                  </tfoot>
                </table>
              </div>
              
              {/* Payment section (Buyer purchase) */}
              <div style={{
                marginTop: '16px',
                padding: '24px',
                border: '1px solid #e1e8ed',
                borderRadius: '12px',
                background: '#ffffff',
                boxShadow: '0 2px 8px rgba(0,0,0,0.04)'
              }}>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '20px', marginBottom: '24px' }}>
                  <div style={{ padding: '12px', background: '#f8faff', borderRadius: '8px' }}>
                    <div style={{ fontSize: '12px', color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.5px', marginBottom: '4px' }}>Cart Amount</div>
                    <div style={{ fontSize: '20px', fontWeight: 800, color: '#1e293b' }}>₹{purchaseTotal.toFixed(2)}</div>
                  </div>
                  {Math.abs(roundedPurchaseTotal - purchaseTotal) > 0.0001 && (
                    <div style={{ padding: '12px', background: '#f8faff', borderRadius: '8px' }}>
                      <div style={{ fontSize: '12px', color: '#64748b', textTransform: 'uppercase', marginBottom: '4px' }}>
                        Round Off ({roundedPurchaseTotal - purchaseTotal > 0 ? '+' : '-'})
                      </div>
                      <div style={{ 
                        fontSize: '20px', 
                        fontWeight: 800, 
                        color: (roundedPurchaseTotal - purchaseTotal) > 0 ? '#10b981' : '#ef4444' 
                      }}>
                        ₹{Math.abs(roundedPurchaseTotal - purchaseTotal).toFixed(2)}
                      </div>
                    </div>
                  )}
                  <div style={{ padding: '12px', background: '#f1f5f9', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                    <div style={{ fontSize: '12px', color: '#64748b', textTransform: 'uppercase', marginBottom: '4px' }}>Final Total</div>
                    <div style={{ fontSize: '20px', fontWeight: 800, color: '#334155' }}>₹{roundedPurchaseTotal.toFixed(2)}</div>
                  </div>
                  <div style={{ padding: '12px', background: '#ecfdf5', borderRadius: '8px', border: '1px solid #d1fae5' }}>
                    <div style={{ fontSize: '12px', color: '#065f46', textTransform: 'uppercase', marginBottom: '4px' }}>Paid Now</div>
                    <div style={{ fontSize: '20px', fontWeight: 800, color: '#059669' }}>₹{purchasePaidNow.toFixed(2)}</div>
                  </div>
                  <div style={{ padding: '12px', background: '#fffbeb', borderRadius: '8px', border: '1px solid #fef3c7' }}>
                    <div style={{ fontSize: '12px', color: '#92400e', textTransform: 'uppercase', marginBottom: '4px' }}>Pending Balance</div>
                    <div style={{ fontSize: '20px', fontWeight: 800, color: '#d97706' }}>₹{purchaseBalance.toFixed(2)}</div>
                  </div>
                </div>

                <div style={{ 
                  display: 'flex', 
                  gap: '24px', 
                  flexWrap: 'wrap', 
                  alignItems: 'center', 
                  padding: '16px', 
                  background: '#f8faff', 
                  borderRadius: '8px',
                  border: '1px solid #e1e8ed' 
                }}>
                  <div style={{ fontWeight: '600', color: '#334155', fontSize: '14px' }}>Payment Status:</div>
                  <label style={{ display: 'flex', gap: '8px', alignItems: 'center', cursor: 'pointer', fontSize: '14px', fontWeight: '500' }}>
                    <input
                      type="radio"
                      name="purchase_payment_status"
                      value="fully_paid"
                      checked={purchasePaymentStatus === 'fully_paid'}
                      onChange={() => {
                        setPurchasePaymentStatus('fully_paid');
                        setPurchasePaidAmount(roundedPurchaseTotal);
                      }}
                      disabled={isSubmitting}
                      style={{ width: '18px', height: '18px', accentColor: '#3b82f6' }}
                    />
                    Full Payment
                  </label>
                  <label style={{ display: 'flex', gap: '8px', alignItems: 'center', cursor: 'pointer', fontSize: '14px', fontWeight: '500' }}>
                    <input
                      type="radio"
                      name="purchase_payment_status"
                      value="partially_paid"
                      checked={purchasePaymentStatus === 'partially_paid'}
                      onChange={() => setPurchasePaymentStatus('partially_paid')}
                      disabled={isSubmitting}
                      style={{ width: '18px', height: '18px', accentColor: '#3b82f6' }}
                    />
                    Partial Payment
                  </label>

                  {purchasePaymentStatus === 'partially_paid' && (
                    <div style={{ display: 'flex', gap: '12px', alignItems: 'center', marginLeft: 'auto' }}>
                      <span style={{ fontSize: '14px', fontWeight: '600', color: '#334155' }}>Enter Amount:</span>
                      <div style={{ position: 'relative' }}>
                        <span style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#64748b' }}>₹</span>
                        <input
                          type="number"
                          min="0"
                          max={roundedPurchaseTotal}
                          value={purchasePaidAmount === 0 ? '' : purchasePaidAmount}
                          placeholder="0"
                          onChange={(e) => {
                            const val = e.target.value;
                            if (val === '') {
                                setPurchasePaidAmount(0);
                                return;
                            }
                            const num = parseInt(val);
                            if (!isNaN(num)) {
                                setPurchasePaidAmount(Math.min(Math.max(0, num), roundedPurchaseTotal));
                            }
                          }}
                          onKeyDown={(e) => {
                            if (['+', '-', '*', '/', 'e', 'E', '.', ','].includes(e.key)) {
                              e.preventDefault();
                            }
                          }}
                          onFocus={(e) => e.target.select()}
                          disabled={isSubmitting}
                          style={{ 
                            width: '120px', 
                            padding: '10px 12px 10px 24px', 
                            border: '1px solid #cbd5e1', 
                            borderRadius: '8px',
                            fontWeight: '700',
                            fontSize: '16px'
                          }}
                        />
                      </div>
                    </div>
                  )}
                </div>
              </div>

              <div style={{ marginTop: '30px', display: 'flex', justifyContent: 'flex-end', gap: '15px' }}>
                <button
                  onClick={() => {
                    if (window.confirm('Discard this purchase list?')) {
                      setSelectedItems([]);
                      setSelectedBuyer('');
                      setBuyerInfo(null);
                      toast.info('Transaction discarded');
                    }
                  }}
                  className="btn btn-secondary"
                  style={{ padding: '12px 24px' }}
                >
                  Discard
                </button>
                <button 
                  onClick={handleSubmit} 
                  className="btn btn-primary" 
                  disabled={isSubmitting || selectedItems.length === 0}
                  style={{ 
                    padding: '12px 40px',
                    fontSize: '16px',
                    opacity: (isSubmitting || selectedItems.length === 0) ? 0.6 : 1,
                    minWidth: '200px'
                  }}
                >
                  {isSubmitting ? 'Saving Transaction...' : 'Confirm Items & Save'}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
      <div style={{ height: '40px' }} />

      {/* Add New Item modal - portaled to body */}
      {showAddItemForm && createPortal(
        <div className="add-item-modal-overlay modal-overlay">
          <div className="modal-content add-item-modal-content" style={{ maxWidth: '640px', maxHeight: '90vh', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
            <div className="modal-header">
              <h3>Add New Product to Inventory</h3>
              <button type="button" className="modal-close" onClick={closeAddItemModal} aria-label="Close">×</button>
            </div>
            <div className="modal-body" style={{ overflow: 'auto', flex: 1, padding: '20px' }}>
              <p style={{ color: '#666', marginBottom: '15px', fontSize: '14px' }}>
                Fill in the product details below. Fields marked with * are required.
              </p>
              <div className="form-row">
                <div className="form-group">
                  <label>Product Name *</label>
                  <input
                    type="text"
                    value={newItem.product_name}
                    onChange={(e) => setNewItem({ ...newItem, product_name: e.target.value })}
                    placeholder="Enter product name"
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Product Code</label>
                  <input
                    type="text"
                    value={newItem.product_code}
                    onChange={(e) => setNewItem({ ...newItem, product_code: e.target.value })}
                  />
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Brand</label>
                  <input
                    type="text"
                    value={newItem.brand}
                    onChange={(e) => setNewItem({ ...newItem, brand: e.target.value })}
                  />
                </div>
                <div className="form-group">
                  <label>HSN Number</label>
                  <input
                    type="text"
                    value={newItem.hsn_number}
                    onChange={(e) => setNewItem({ ...newItem, hsn_number: e.target.value })}
                  />
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Purchase Rate *</label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={newItem.purchase_rate === 0 ? '' : newItem.purchase_rate}
                    onChange={(e) => {
                      const val = e.target.value;
                      const purchaseRate = val === '' ? 0 : parseFloat(val) || 0;
                      setNewItem({ ...newItem, purchase_rate: purchaseRate });
                    }}
                    placeholder="0.00"
                    required
                    style={{
                      borderColor: newItem.sale_rate > 0 && newItem.purchase_rate > 0 && newItem.sale_rate < newItem.purchase_rate ? '#dc3545' : undefined
                    }}
                  />
                  {newItem.sale_rate > 0 && newItem.purchase_rate > 0 && newItem.sale_rate < newItem.purchase_rate && (
                    <small style={{ color: '#dc3545', display: 'block', marginTop: '5px' }}>
                      ⚠️ Purchase rate cannot be greater than sale rate
                    </small>
                  )}
                </div>
                <div className="form-group">
                  <label>Tax Rate (%)</label>
                  <select
                    value={newItem.tax_rate}
                    onChange={(e) => {
                      const selectedTaxRate = parseFloat(e.target.value);
                      const validTaxRates = [5, 18, 28];
                      const finalTaxRate = validTaxRates.includes(selectedTaxRate) ? selectedTaxRate : 18;
                      setNewItem({ ...newItem, tax_rate: finalTaxRate });
                    }}
                  >
                    <option value="5">5%</option>
                    <option value="18">18%</option>
                    <option value="28">28%</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Sale Rate *</label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={newItem.sale_rate === 0 ? '' : newItem.sale_rate}
                    onChange={(e) => {
                      const val = e.target.value;
                      const saleRate = val === '' ? 0 : parseFloat(val) || 0;
                      setNewItem({ ...newItem, sale_rate: saleRate });
                    }}
                    placeholder="0.00"
                    required
                    style={{
                      borderColor: newItem.sale_rate > 0 && newItem.purchase_rate > 0 && newItem.sale_rate < newItem.purchase_rate ? '#dc3545' : undefined
                    }}
                  />
                  {newItem.sale_rate > 0 && newItem.purchase_rate > 0 && newItem.sale_rate < newItem.purchase_rate && (
                    <small style={{ color: '#dc3545', display: 'block', marginTop: '5px' }}>
                      ⚠️ Sale rate must be ≥ purchase rate
                    </small>
                  )}
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Quantity *</label>
                  <input
                    type="number"
                    // min="0"
                    value={newItem.quantity === 0 ? '' : newItem.quantity}
                    onChange={(e) => {
                      const val = e.target.value;
                      setNewItem({ ...newItem, quantity: val === '' ? 0 : parseInt(val) || 0 });
                    }}
                    // placeholder="0"
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Alert Quantity</label>
                  <input
                    type="number"
                    value={newItem.alert_quantity === 0 ? '' : newItem.alert_quantity}
                    onChange={(e) => {
                      const val = e.target.value;
                      setNewItem({ ...newItem, alert_quantity: val === '' ? 0 : parseInt(val) || 0 });
                    }}
                  />
                </div>
                <div className="form-group">
                  <label>Rack Number</label>
                  <input
                    type="text"
                    value={newItem.rack_number}
                    onChange={(e) => setNewItem({ ...newItem, rack_number: e.target.value })}
                  />
                </div>
              </div>
              <div className="form-group">
                <label>Remarks (Max 200 characters)</label>
                <textarea
                  value={newItem.remarks}
                  onChange={(e) => {
                    const value = e.target.value;
                    if (value.length <= 200) {
                      setNewItem({ ...newItem, remarks: value });
                    }
                  }}
                  rows="3"
                  maxLength={200}
                  placeholder="Enter remarks..."
                />
                <small style={{ color: '#666', fontSize: '12px' }}>
                  {newItem.remarks?.length || 0}/200 characters
                </small>
              </div>
              <div className="form-group">
                <label>Product Image (Max 3MB)</label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={(e) => {
                    const file = e.target.files[0];
                    if (file) {
                      if (file.size > 3 * 1024 * 1024) {
                        alert('Image size must be less than 3MB');
                        e.target.value = '';
                        return;
                      }
                      setItemImage(file);
                    }
                  }}
                />
                {itemImage && (
                  <div style={{ marginTop: '10px' }}>
                    <img 
                      src={URL.createObjectURL(itemImage)} 
                      alt="Preview" 
                      style={{ maxWidth: '200px', maxHeight: '200px' }}
                    />
                    <button
                      type="button"
                      onClick={() => {
                        setItemImage(null);
                        document.querySelector('input[type="file"]').value = '';
                      }}
                      style={{ marginLeft: '10px', padding: '5px 10px' }}
                    >
                      Remove
                    </button>
                  </div>
                )}
              </div>

              <div className="form-actions">
                <button 
                  onClick={handleAddNewItem} 
                  className="btn btn-primary"
                  disabled={isAddingNewItem || isSubmitting}
                  style={{
                    opacity: (isAddingNewItem || isSubmitting) ? 0.6 : 1,
                    cursor: (isAddingNewItem || isSubmitting) ? 'not-allowed' : 'pointer'
                  }}
                >
                  {isAddingNewItem ? 'Adding...' : 'Add to Inventory'}
                </button>
                <button type="button" onClick={closeAddItemModal} className="btn btn-secondary">Cancel</button>
              </div>
            </div>
          </div>
        </div>,
        document.body
      )}

    </Layout>
  );
};

export default AddItem;


